class WindowedAggSink {
  constructor(windowMs, latenessMs) {
    this.windowMs = windowMs;
    this.latenessMs = latenessMs;
    this.state = new Map(); // windowStart -> deviceId -> sum
  }
  onMessage(msg) {
    // msg: { deviceId, value, timestamp, offset }
    const ws = this.windowStartFor(msg.timestamp);
    const bucket = (this.state.get(ws) = this.state.get(ws) || new Map());
    bucket.set(msg.deviceId, (bucket.get(msg.deviceId) || 0) + msg.value);
  }
  onWindowBoundary(now) {
    // emit and clean up windows that ended before now - latenessMx
  }
  commitOffsets() {
    // persist offsets after successful emits
  }
  getTotals() {
    // return current in-memory totals for inspection
  }
  windowStartFor(ts) {
    return Math.floor(ts / this.windowMs) * this.windowMs;
  }
}
```

